# Usage (from starter/): bash ../advanced/run.sh <split> <run name> [extra agent.py args]
# Agent model and grounding rules are fixed here; retrieval/agent options come from the extra args.
split=$1; name=$2; shift 2
BOOK='Chapters 1-5 of the textbook "Introductory Statistics 2e" (OpenStax). Context chunks are either page text or a model-generated visual description of the figures on a page'
RULES='Extra rules: (1) Cite exactly the chunk ids whose text states each claim; never cite a chunk that does not contain the claim. (2) State only facts written in the cited chunks; do not add general statistics knowledge, even if true. (3) When page text or a table gives an exact number, use it; values marked "≈" in visual descriptions are estimates: use them only when no exact value exists and say they are approximate. (4) For calculations, show the numbers you used and where they come from. (5) If the question asks about a specific method, test or term that is not named in the context, call abstain; never answer with a different method instead. (6) Before calling answer, delete every sentence whose content is not stated in a cited chunk. (7) If the question asks about a group, category, year or value that does not appear in the named table or figure, call abstain; never use a value from a different table, figure or group. (8) If one part of the question is not supported by the context yet, search specifically for that part (for a figure, search its label, e.g. "Figure 2.5") before answering.'
PYTHONUTF8=1 python agent.py --split "$split" --data-dir ../advanced/data --strategy ADV --model gpt-4.1-mini --book "$BOOK" \
  --example-id 'openstax-intro-stats-2e:p85:visual' --extra-rules "$RULES" --context-order rank --stop-repeat "$@" \
  --output "../advanced/results/$split-$name"
